import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`property-churn-predictor`,heroTitle:`Predict property churn before it happens`,heroSubtitle:`Perplexity Computer analyzes your tenant data, scores churn risk for every property, and builds a retention playbook — automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload tenant data`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls`,inputFilePrefill:`Analyze the uploaded file containing property and tenant data. 1) Parse all tenant records — extract lease terms, renewal history, payment patterns, maintenance requests, occupancy duration, and any demographic or property-type fields. 2) Score each property or unit for churn risk on a 1-100 scale based on late payments, lease expiration proximity, complaint frequency, and tenure length. 3) Segment properties into High, Medium, and Low churn risk tiers. 4) Identify the top 5 churn drivers across the portfolio with supporting data. 5) For each High-risk property, generate a specific retention action plan — rent adjustment recommendations, maintenance priorities, lease incentive timing, and outreach templates. 6) Deliver a summary dashboard with portfolio-wide churn rate forecast, revenue at risk, and a prioritized list of properties needing immediate attention.`,heroOverlaySteps:[`Parsing tenant records, lease terms, and payment history`,`Scoring churn risk for every property in your portfolio`,`Identifying top churn drivers and revenue at risk`,`Risk scores, retention playbook, and revenue forecast — ready to act on`],generatingSteps:[`Reading the uploaded file to extract tenant records, lease data, and payment patterns`,`Designing an agent to score churn risk and segment properties by retention urgency`,`Configuring churn driver analysis and revenue-at-risk calculations`,`Setting up retention playbooks and portfolio-wide forecasting`],featureSectionTitle:`From tenant data to retention strategy`,featureCardTitles:[`Connects to your property stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Airtable, Notion, Slack, Google Drive — Computer feeds churn scores and retention plans directly into the tools your property team already uses.`,`Property-level churn risk scores. Portfolio revenue-at-risk forecasts. Top churn driver analysis. Unit-specific retention action plans with outreach templates.`],capabilitySectionTitle:`Your retention team, on autopilot`,capabilitySectionSubtitle:`Upload your tenant data, step away, come back to a complete churn prevention strategy.`,capabilityCards:[{title:`Churn Risk Scoring`,description:`Computer can score every property for churn risk — analyzing payment history, lease timelines, complaint frequency, and tenure to flag units before tenants leave.`},{title:`Revenue Forecasting`,description:`Computer can calculate revenue at risk across your portfolio — broken down by property, region, and risk tier so you know exactly what's at stake.`},{title:`Retention Playbooks`,description:`Computer can generate unit-specific retention plans — rent adjustments, maintenance priorities, lease incentives, and outreach timing tailored to each at-risk tenant.`},{title:`Connect Your Tools`,description:`Computer can sync with Google Sheets, Airtable, Notion, Slack, and Google Drive — build workflows across your entire property management stack.`},{title:`Track Over Time`,description:`Computer can remember past churn scores and tenant histories across sessions — so every analysis shows trends, not just snapshots.`},{title:`Monitor & Alert`,description:`Computer can re-score your portfolio on a schedule and alert you when a property's churn risk spikes or a lease renewal window is closing.`}]});export{t as default};
